import{NextResponse}from"next/server";import{prisma}from"@/lib/prisma";import{createExternalTrade}from"@/lib/external";export async function GET(){return NextResponse.json(await prisma.externalTrade.findMany({include:{item:true},orderBy:{tradeDate:"desc"}}))}export async function POST(r:Request){try{const b=await r.json(),x=await prisma.$transaction(tx=>createExternalTrade(tx,b));return NextResponse.json(x,{status:201})}catch(e){return NextResponse.json({error:e instanceof Error?e.message:"تعذر الحفظ"},{status:400})}}
